// Builds a Telegram message in HTML mode from any data, escaping it so nothing in the data can break the message.
// Why: without a parse mode n8n's Telegram node sends legacy Markdown, where a stray "*", "`" or "[" in the data
// (AI text, prices like "50% *off*", links) makes Telegram reject the message with "can't parse entities".
// Input: one item per message with `title`, `fields` (object: label -> value) and optional `link`.
const settings = $('Set message settings').first().json;
const MAX = 4096; // Telegram's limit for one message

const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

return $input.all().map((item) => {
  const data = item.json;
  const lines = [`<b>${escapeHtml(data.title || settings.defaultTitle)}</b>`];
  for (const [label, value] of Object.entries(data.fields || {})) {
    if (value === undefined || value === null || value === '') continue;
    const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
    lines.push(`<b>${escapeHtml(label)}:</b> ${escapeHtml(text.slice(0, settings.maxFieldLength))}`);
  }
  if (data.link && /^https?:\/\//i.test(data.link)) {
    lines.push(`<a href="${escapeHtml(data.link).replace(/"/g, '&quot;')}">${escapeHtml(settings.linkText)}</a>`);
  }
  let text = lines.join('\n');
  // Too long: cut at a line break so no tag is left open, and say so.
  if (text.length > MAX) {
    const cut = text.slice(0, MAX - 40);
    text = cut.slice(0, cut.lastIndexOf('\n')) + '\n<i>… message shortened</i>';
  }
  return { json: { chatId: settings.telegramChatId, text } };
});
